import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('APP_SECRET', 'dev-secret-key-change-me')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_session_token(token):
    """Verify HMAC-based session token"""
    if not token:
        return None
    parts = token.split(':')
    if len(parts) != 2:
        return None
    username, sig = parts
    expected = hmac.new(SECRET_KEY.encode(), username.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return username
    return None

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    auth = request.headers.get('X-Session-Token')
    current_user = verify_session_token(auth)
    if not current_user:
        return jsonify({'error': 'unauthorized'}), 401

    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Whitelist allowed search fields
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    db = get_db()
    # Build query with field from whitelist - safe
    # But value is directly interpolated - VULNERABLE
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, username) VALUES (?, ?)",
            (f"search:{field}:{value[:50]}", current_user)
        )
        db.commit()
        return jsonify({'results': users})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/profile', methods=['GET'])
def get_profile():
    auth = request.headers.get('X-Session-Token')
    current_user = verify_session_token(auth)
    if not current_user:
        return jsonify({'error': 'unauthorized'}), 401

    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role FROM users WHERE username = ?",
        (current_user,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
